namespace sv_e7cbaa9e7c994ee9b9846e80d8965e19.Services;

public class NotificationMessage
{
    public int Id { get; set; }
    public string Text { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<NotificationMessage> _notifications = new()
    {
        new() { Id = 1, Text = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
        new() { Id = 2, Text = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        new() { Id = 3, Text = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) },
    };

    private static readonly string[] SampleMessages =
    [
        "System maintenance scheduled for tonight.",
        "You have a new follower!",
        "Your report is ready to download.",
        "Security alert: new login detected.",
        "Weekly digest is available.",
        "A teammate mentioned you in a comment.",
    ];

    public Task<List<NotificationMessage>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<NotificationMessage>> GetNotificationsSinceAsync(int lastId)
    {
        // Simulate occasional new notifications
        lock (_notifications)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance each poll
            {
                var msg = new NotificationMessage
                {
                    Id = _nextId++,
                    Text = SampleMessages[Random.Shared.Next(SampleMessages.Length)],
                    Timestamp = DateTime.UtcNow
                };
                _notifications.Add(msg);
            }

            var newer = _notifications.Where(n => n.Id > lastId).ToList();
            return Task.FromResult(newer);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@using sv_e7cbaa9e7c994ee9b9846e80d8965e19.Services
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Text</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationMessage>? PersistedNotifications { get; set; }

    private List<NotificationMessage> notifications = new();
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationSvc.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(5000, ct);

            var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

