@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@using sv_e7cbaa9e7c994ee9b9846e80d8965e19.Services
@inject NotificationService NotificationSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@notifications.Count</span></h1>

@if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Text</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationMessage> notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistSubscription = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (!ApplicationState.TryTakeFromJson<List<NotificationMessage>>("notifications", out var restored))
        {
            notifications = await NotificationSvc.GetNotificationsAsync();
        }
        else
        {
            notifications = restored!;
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(5000, ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _persistSubscription.Dispose();
    }
}

